const priorRows = $('Load Snapshots').all().map(i => i.json);
const prior = {};
for (const r of priorRows) prior[r.watch_url] = r;

const reg = $('Load Registry').all().map(i => i.json);
const fetched = $input.all().map(i => i.json);
const now = new Date().toISOString();

function textify(html) {
  return String(html || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<nav[\s\S]*?<\/nav>/gi, ' ')
    .replace(/<footer[\s\S]*?<\/footer>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;|&amp;|&quot;|&#39;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function djb2(str) {
  let h = 5381;
  for (let i = 0; i < str.length; i++) h = (((h << 5) + h) ^ str.charCodeAt(i)) >>> 0;
  return h.toString(16);
}

function sentences(t) {
  return t.split(/(?<=[.!?])\s+/).map(s => s.trim()).filter(s => s.length > 40);
}

const out = [];
for (let i = 0; i < reg.length; i++) {
  const r = reg[i];
  const f = fetched[i] || {};
  const text = textify(f.html);

  if (!text || text.length < 200) {
    out.push({ json: { ...r, status: 'fetch_failed', changed: false, added_text: '', content_text: '', content_hash: '', last_checked: now, last_changed: (prior[r.watch_url] || {}).last_changed || '' } });
    continue;
  }

  const hash = djb2(text);
  const before = prior[r.watch_url];

  if (!before) {
    out.push({ json: { ...r, status: 'baseline_created', changed: false, added_text: '', content_text: text.slice(0, 20000), content_hash: hash, last_checked: now, last_changed: now } });
    continue;
  }

  if (before.content_hash === hash) {
    out.push({ json: { ...r, status: 'unchanged', changed: false, added_text: '', content_text: text.slice(0, 20000), content_hash: hash, last_checked: now, last_changed: before.last_changed } });
    continue;
  }

  const oldSet = new Set(sentences(before.content_text || ''));
  const added = sentences(text).filter(s => !oldSet.has(s));
  out.push({ json: { ...r, status: 'changed', changed: true, added_text: added.join('\n').slice(0, 6000), added_count: added.length, content_text: text.slice(0, 20000), content_hash: hash, last_checked: now, last_changed: now } });
}

return out;

const rows = $('Hash and Diff').all().map(i => i.json);
const changed = rows.filter(r => r.changed && r.added_text && r.added_text.length > 60);

return changed.map(r => {
  const prompt = 'You monitor competitors on behalf of a law firm marketing agency.

OUR CLIENT: ' + r.client_firm + ' (' + r.practice_area + ', ' + r.market + ')
COMPETITOR: ' + r.competitor_name + '
PAGE: ' + r.page_label + ' (' + r.watch_url + ')

Below is text that is NEW on this competitor page since last month. Report only what would change how our client competes.

CATEGORIES:
- AWARD_OR_RANKING, PERSONNEL, PRACTICE_EXPANSION, CASE_RESULT, BRAND_CHANGE, COMPARATIVE_CLAIM, MEDIA_MOMENT

MATERIALITY SCALE - calibrate against these anchors, do not cluster:

0.0-0.2 ROUTINE. Reworded copy, a new blog post on a generic legal topic, formatting or navigation changes, seasonal safety tips, boilerplate. Most changes belong here.

0.3-0.5 MINOR. A new case result of ordinary size for this practice area (a personal injury firm publishes these constantly). A new associate added. One more award listing among many. A substantive blog post on a topic our client also targets.

0.6-0.7 NOTABLE. A case result well above what this competitor normally publishes. A senior or well known attorney joining. A significant ranking such as a Best Lawyers Law Firm of the Year listing. A visible repositioning of an existing practice area.

0.8-0.9 SIGNIFICANT. A record setting or headline verdict that resets market expectations. A name partner joining or departing. A new office, new city, or entry into a new practice area. A major media moment such as leading a nationally covered case.

1.0 CRITICAL. A merger or acquisition. Firm dissolution. Disciplinary or disbarment news. Advertising copy that directly targets or disparages our client.

Be strict. If you are scoring most items above 0.6 you are miscalibrated. A brief that flags everything gets ignored, and then it protects nobody.

NEW TEXT:
"""
' + r.added_text + '
"""

Respond with ONLY valid JSON, no preamble or code fences:
{"findings": [{"category": "CASE_RESULT", "headline": "one short line", "detail": "one or two sentences of what changed", "why_it_matters": "one sentence on the impact for our client", "materiality": 0.0}]}

Return an empty findings array if nothing clears 0.3.';
  return { json: { ...r, scoring_prompt: prompt } };
});

const src = $('Prepare Materiality Scoring').all().map(i => i.json);
const resp = $input.all().map(i => i.json);
const all = $('Hash and Diff').all().map(i => i.json);
const MATERIAL = 0.65;

const byClient = {};
const scoreSpread = [];
let errors = 0;
let inTok = 0, outTok = 0;

for (let i = 0; i < src.length; i++) {
  const r = src[i];
  const raw = resp[i] || {};
  let findings = [];
  try {
    if (raw.error) throw new Error(raw.error.message || 'api error');
    const blocks = Array.isArray(raw.content) ? raw.content : [];
    const textBlock = blocks.find(b => b && b.type === 'text');
    if (!textBlock || !textBlock.text) throw new Error('no text block');
    const u = raw.usage || {};
    inTok += u.input_tokens || 0;
    outTok += u.output_tokens || 0;
    const cleaned = textBlock.text.replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
    const parsed = JSON.parse(cleaned);
    findings = Array.isArray(parsed.findings) ? parsed.findings : [];
  } catch (e) {
    errors++;
    findings = [{ category: 'REVIEW_MANUALLY', headline: 'Change detected but scoring failed', detail: (r.added_text || '').slice(0, 300), why_it_matters: 'Scoring unavailable: ' + e.message, materiality: 1 }];
  }

  for (const f of findings) {
    scoreSpread.push(f.materiality ?? 0);
    if ((f.materiality ?? 0) < MATERIAL) continue;
    byClient[r.client_id] = byClient[r.client_id] || { client_id: r.client_id, client_firm: r.client_firm, market: r.market, practice_area: r.practice_area, items: [] };
    byClient[r.client_id].items.push({ competitor: r.competitor_name, source_url: r.watch_url, page: r.page_label, category: f.category, headline: f.headline, detail: f.detail, why_it_matters: f.why_it_matters, materiality: f.materiality });
  }
}

const digests = Object.keys(byClient).map(k => {
  const d = byClient[k];
  d.items.sort((a, b) => (b.materiality || 0) - (a.materiality || 0));
  return d;
});

const cost = (inTok / 1e6) * 2 + (outTok / 1e6) * 10;
scoreSpread.sort((a, b) => a - b);

return [{
  json: {
    run_at: new Date().toISOString(),
    threshold: MATERIAL,
    coverage: {
      pages_watched: all.length,
      fetch_failed: all.filter(r => r.status === 'fetch_failed').length,
      baselines_created: all.filter(r => r.status === 'baseline_created').length,
      unchanged: all.filter(r => r.status === 'unchanged').length,
      changed: all.filter(r => r.status === 'changed').length
    },
    scoring: {
      pages_scored: src.length,
      scoring_errors: errors,
      candidate_findings: scoreSpread.length,
      score_spread: scoreSpread,
      note: 'score_spread should span low and high values. If it clusters near the threshold the scale is miscalibrated.'
    },
    signal_ratio: {
      changes_detected: src.length,
      material_findings: digests.reduce((s, d) => s + d.items.length, 0),
      note: 'If material_findings approaches changes_detected, the bar is too low and the brief will become noise.'
    },
    cost_usd: Number(cost.toFixed(4)),
    digests
  }
}];

const run = $input.first().json;
const digests = Array.isArray(run.digests) ? run.digests : [];
const period = new Date(run.run_at || Date.now()).toLocaleDateString('en-US', { month: 'long', year: 'numeric' });

if (digests.length === 0) {
  return [{ json: {
    client_id: 'ALL',
    client_firm: 'All clients',
    period,
    quiet: true,
    pages_watched: run.coverage.pages_watched,
    brief_prompt: 'Write two sentences for a law firm leadership team confirming that competitor monitoring ran for ' + period + ' across ' + run.coverage.pages_watched + ' competitor pages and found no significant changes worth their attention. Plain business English. Do not mention software, AI, scoring, or any system detail. Do not pad it.'
  } }];
}

return digests.map(d => {
  const lines = d.items.map((it, n) =>
    (n + 1) + '. COMPETITOR: ' + it.competitor +
    '\n   WHAT CHANGED: ' + it.headline +
    '\n   DETAIL: ' + it.detail +
    '\n   COMPETITIVE IMPACT: ' + it.why_it_matters +
    '\n   SOURCE: ' + it.source_url
  ).join('\n\n');

  const prompt = 'You are writing the monthly competitive brief for the leadership team at ' + d.client_firm + ', a ' + String(d.practice_area).replace(/_/g, ' ') + ' law firm in ' + d.market + '.\n\nYour readers are attorneys and firm executives. They are not technical. Write the way a sharp strategy consultant writes a memo.\n\nHARD RULES:\n- Never mention AI, models, scoring, confidence, thresholds, automation, workflows, or any system detail. The reader must never sense a machine was involved.\n- No jargon, no bullet-point fragments, no headers like OVERVIEW or ANALYSIS.\n- Name competitors plainly and say who they are in a few words the first time they appear.\n- Every claim must trace to the findings below. Invent nothing. If something is unclear, leave it out.\n- Be brief. A partner should read this in ninety seconds.\n\nSTRUCTURE:\n1. A short opening paragraph naming the single most important development this month and what it means for the firm.\n2. One short paragraph per competitor that had activity. Say who they are, what changed, and why the firm should care.\n3. A closing paragraph headed exactly "What we recommend" with two or three specific, concrete actions the firm could take in response. Recommend marketing and positioning actions, not legal strategy.\n\nPeriod: ' + period + '\n\nFINDINGS:\n' + lines + '\n\nRespond with ONLY the brief text. No preamble, no JSON, no code fences, no title line.';

  return { json: {
    client_id: d.client_id,
    client_firm: d.client_firm,
    market: d.market,
    period,
    quiet: false,
    finding_count: d.items.length,
    competitors: d.items.map(i => i.competitor).filter((v, i, a) => a.indexOf(v) === i),
    items: d.items,
    brief_prompt: prompt
  } };
});

const src = $('Prepare Brief Input').all().map(i => i.json);
const resp = $input.all().map(i => i.json);
const run = $('Build Client Digests').first().json;

const briefs = [];
let errors = 0;
let inTok = 0, outTok = 0;

for (let i = 0; i < src.length; i++) {
  const s = src[i];
  const raw = resp[i] || {};
  let text = '';

  try {
    if (raw.error) throw new Error(raw.error.message || 'api error');
    const blocks = Array.isArray(raw.content) ? raw.content : [];
    const textBlock = blocks.find(b => b && b.type === 'text');
    if (!textBlock || !textBlock.text) throw new Error('no text block');
    const u = raw.usage || {};
    inTok += u.input_tokens || 0;
    outTok += u.output_tokens || 0;
    text = textBlock.text.trim();
  } catch (e) {
    errors++;
    text = 'This brief could not be generated automatically this month. The underlying findings are attached below and need a manual write-up before sending.';
  }

  const title = 'Competitive Brief - ' + s.client_firm + ' - ' + s.period;
  const sources = (s.items || []).map(it => '- ' + it.competitor + ': ' + it.source_url)
    .filter((v, idx, a) => a.indexOf(v) === idx);

  briefs.push({
    client_id: s.client_id,
    client_firm: s.client_firm,
    period: s.period,
    title,
    brief_text: text,
    competitors_covered: s.competitors || [],
    finding_count: s.finding_count || 0,
    sources,
    ready_to_send: errors === 0 && !s.quiet,
    full_document: title + '\n' + '='.repeat(title.length) + '\n\n' + text + (sources.length ? '\n\nSources\n' + sources.join('\n') : '')
  });
}

const briefCost = (inTok / 1e6) * 2 + (outTok / 1e6) * 10;

return [{
  json: {
    run_at: run.run_at,
    period: src[0] ? src[0].period : '',
    briefs_written: briefs.length,
    brief_errors: errors,
    coverage: run.coverage,
    scoring: run.scoring,
    signal_ratio: run.signal_ratio,
    cost_usd_total: Number((Number(run.cost_usd || 0) + briefCost).toFixed(4)),
    briefs
  }
}];
